const n=document.querySelectorAll(".reveal");if(n.length){const e=new IntersectionObserver(t=>{t.forEach(o=>{o.isIntersecting&&(o.target.classList.add("is-visible"),e.unobserve(o.target))})},{threshold:.08});n.forEach(t=>e.observe(t))}const s=document.getElementById("nav-toggle"),c=document.getElementById("main-nav");s?.addEventListener("click",()=>{c?.classList.toggle("open");const e=c?.classList.contains("open")??!1;s.setAttribute("aria-expanded",String(e))});const a=document.querySelector("[data-header]"),l=()=>a?.classList.toggle("is-scrolled",window.scrollY>40);l();window.addEventListener("scroll",l,{passive:!0});document.getElementById("footer-cookie-settings")?.addEventListener("click",()=>{localStorage.removeItem("rosengarten-cookie-consent"),document.getElementById("cookie-banner")?.classList.add("show")});
